solutionCode:
fun getValidReadings(readings: List<Double?>): List<Double> {
    return readings.filterNotNull()
}

fun averageReading(readings: List<Double?>): Double {
    val valid = readings.filterNotNull()
    return if (valid.isEmpty()) 0.0 else valid.average()
}

