import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testGetValidReadings() {
        Assert.assertEquals(listOf(42.5, 38.0), getValidReadings(listOf(42.5, null, 38.0)))
    }

    @Test
    fun testGetValidReadingsAllNull() {
        Assert.assertEquals(emptyList<Double>(), getValidReadings(listOf(null, null, null)))
    }

    @Test
    fun testGetValidReadingsNoNulls() {
        Assert.assertEquals(listOf(10.0, 20.0, 30.0), getValidReadings(listOf(10.0, 20.0, 30.0)))
    }

    @Test
    fun testAverageReading() {
        Assert.assertEquals(40.25, averageReading(listOf(42.5, null, 38.0)), 0.01)
    }

    @Test
    fun testAverageReadingAllNull() {
        Assert.assertEquals(0.0, averageReading(listOf(null, null)), 0.01)
    }

    @Test
    fun testAverageReadingSingle() {
        Assert.assertEquals(42.5, averageReading(listOf(42.5)), 0.01)
    }
}
